    static Set<Origin> origins(Packet p){Set<Origin> result=new HashSet<>();for(Item item:p.items)if(item.atom.predicate.equals("r"))for(Slot slot:item.atom.arguments)if(slot.origin!=null)result.add(slot.origin);return result;}
    static void cases()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);"),a=bind(false,"!$u $v a(u,1)&&a(v,1)&&hidden(u,1);"),b=bind(false,"!@u b(u,2);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);SessionRun forward=null;
        require(pool.sources.size()==1&&a.primary.size()==1&&a.primary.get(0).witnesses()==2&&pool.sources.contains(a.primary.get(0).source)&&pool.snapshot==a&&pool.declarations.size()==x.primary.size(),"ONE actual full private witness row/two binders; non-witness declarations kept separately");
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Frame f=new Frame(x,order,p,pools);SessionRun initial=run(f,8,WORK,4096);audited(f,p,pools,f.units,f.compounds,8,initial);Set<Origin> actual=origins(initial.result.output.packet);require(actual.size()==2&&actual.stream().allMatch(o->pool.sources.contains(o.source)),"two distinct rigid Origins from SAME physical Source retained");Set<Origin> routes=new HashSet<>();for(Round round:initial.result.history)for(ConstraintTransfer t:round.barrier.branches.values())for(ContextUniversalOriginBindings.Route route:t.bindings.routes)routes.add(route.origin);require(routes.containsAll(actual),"actual theorem-specific parameter routes cover both private binders");
            SessionRun finalState=stable(f,2);Packet common=finalState.result.output.packet;require(origins(common).equals(actual)&&common.items.stream().filter(i->i.atom.predicate.equals("r")).count()==2,"both Origins survive repeated barrier authentication, no alias collapse");require(!ContextUniversalGroupedRoundsRunner.has(common,"a")&&!ContextUniversalGroupedRoundsRunner.has(common,"hidden"),"raw private bundle withheld despite shared physical Source");require(common.items.stream().filter(i->i.atom.predicate.equals("r")).flatMap(i->i.proofs.stream()).allMatch(s->s.depth==1&&s.sources.size()==3),"all fixed Origin products at native minimum1/all three Sources");PrivatePool out=finalState.result.output.privatePools.get(pool.cut);require(out!=null&&out.snapshot==a&&out.x==x&&out.common==common&&out.sources.equals(pool.sources)&&out.declarations.size()==pool.declarations.size()&&ContextUniversalGroupedRoundsRunner.has(out.local,"a")&&ContextUniversalGroupedRoundsRunner.has(out.local,"hidden")&&ContextUniversalGroupedRoundsRunner.has(out.local,"r"),"actual private frame/rebased local knowledge and whole manifest preserved");require(pool.common==p&&!ContextUniversalGroupedRoundsRunner.has(pool.local,"r"),"original immutable private input remains unchanged");if(forward!=null)same(forward.result,finalState.result);forward=finalState;}
        SessionRun trustedForward=null;Frame firstTrusted=null;List<Snapshot> groups=new ArrayList<>();for(List<Snapshot> members:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Snapshot group=org.kanger.ContextProductionNativeBinding.trusted("private-matrix",members,WORK);PrivatePool grouped=ContextWitnessResultTransport.privatePool(p,x,group,WORK);Frame f=new Frame(x,Collections.singletonList(group),p,Collections.singletonMap(grouped.cut,grouped));groups.add(group);if(firstTrusted==null)firstTrusted=f;SessionRun r=stable(f,2);require(grouped.snapshot==group&&grouped.sources.equals(pool.sources)&&grouped.declarations.size()==pool.declarations.size()+1,"trusted private manifest preserves actual member seed Source and ordinary member rule");require(origins(r.result.output.packet).equals(origins(forward.result.output.packet))&&!ContextUniversalGroupedRoundsRunner.has(r.result.output.packet,"a")&&!ContextUniversalGroupedRoundsRunner.has(r.result.output.packet,"hidden")&&!ContextUniversalGroupedRoundsRunner.has(r.result.output.packet,"b"),"trusted private binders retain physical identity without raw disclosure");if(trustedForward!=null){sameShared(trustedForward.result,r.result);PrivatePool previous=trustedForward.result.output.privatePools.values().iterator().next(),current=r.result.output.privatePools.values().iterator().next();require(previous.cut.members.equals(current.cut.members)&&Objects.equals(previous.cut.trustedGroup,current.cut.trustedGroup)&&previous.sources.equals(current.sources)&&ContextWitnessResultTransport.sameContents(previous.local,current.local,WORK),"distinct actual trusted routing cuts retain same complete member/private Source-depth pool");Map<org.kanger.ContextProductionCapture.Source,String> before=new HashMap<>(),after=new HashMap<>();for(org.kanger.ContextProductionInputs.Declaration d:previous.declarations)before.put(d.source,d.statement);for(org.kanger.ContextProductionInputs.Declaration d:current.declarations)after.put(d.source,d.statement);require(before.equals(after),"whole declaration contents equal by actual physical Source across member routing order");}trustedForward=r;}
        SessionRun overlap=ContextUniversalGroupedRounds.runWithValidationReuse(x,groups,p,firstTrusted.pools,firstTrusted.units,firstTrusted.compounds,firstTrusted.limits,firstTrusted.local,8,WORK,4096);incomplete(overlap,"reordered trusted groups cannot bypass physical member overlap despite distinct routing cuts");require(overlap.result.phase.equals("preflight"),"physical context overlap rejected before local proof/product work");noStableAudit(firstTrusted,overlap);
        System.out.println("CONTINUATION_PRIVATE cutOrders=2 trustedMemberOrders=2 sameSourceOrigins=2 continuationsPerCase=2 reorderedOverlapRefused=true");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("continuation-private-").toString());cases();System.out.println("MATRIX_SCOPES audits="+audits+" receiptRechecks="+receipts+" continuations="+continuations);System.out.println("CONTEXT_UNIVERSAL_CONTINUATION_PRIVATE_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
